mapper.select:
/* TbmAi02Mapper.selectSessionGenSource */
SELECT
      SESSION_CD    AS sessionCd
    , TITLE         AS title
    , SITE_CD       AS siteCd
    , STATUS_CD     AS statusCd
FROM TB_TBM_SESSION
WHERE SESSION_CD = #{sessionCd}
  AND CMPNY_CD = #{cmpnyCd}
  AND DEL_YN = 'N'

/* TbmAi02Mapper.countUserSiteAuth */
SELECT
      COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'
